  const isP02 = k => (META[k] || {}).group === "p02";
  const isP05 = k => (META[k] || {}).group === "p05";
  const isP07 = k => /^p07[ab]$/.test((META[k] || {}).group || "");
  const NH = D.nh || null;
  const kpi07For = k => (NH && NH.by_variant[k] && NH.by_variant[k].kpi07) || null;
  const kpiFrac = (k, m) => { const g = kpi07For(k); return g && g.frac && g.frac[m] != null ? g.frac[m] : null; };

  // группы — из vrows (строки выбора прежней страницы)
  const GROUPS = [], GROUP = {}, ORDER = [];
  (D.vrows || []).forEach((g, i) => {
