  });
  const MAIN_NAMES = {btc4h_trail: "Главный · BTC 4 ч, трейл 1/1", btc4h_take: "BTC 4 ч, тейк 1,75 %", cand: "BTC 1 ч, трейл 1/1",
    nofilter: "Без фильтра просадки", g85: "Г-85а · одна заявка P+1", g85b: "Г-85б · 3 заявки, ширина в σ"};
  function nameOf(k) {
    if (MAIN_NAMES[k]) return MAIN_NAMES[k];
    const m = META[k] || {};
    if (m.group === "p05") return "П-05 · " + p05Label(k.slice(4));
    if (m.group === "p02") return "П-02 · " + (m.pill || m.label);
    if (isP07(k)) return (m.group === "p07a" ? "Г-85а" : "Г-85б") + " · " + m.axis + (/[=≤≥<>]/.test(m.btn) ? ": " : " = ") + m.btn;
    return m.pill || m.label || k;
  }
  // вердикт П-02 по строке раздела «Гипотезы П-02»: ключ варианта → «Г-NN» (как в прежней странице)
  function p02Verdict(key) {
    const m = key.match(/\d+/); if (!m || !D.p02) return "";
    const r = D.p02.rows.find(x => x.h.startsWith("Г-" + m[0] + " "));
    return r ? r.v10 : "";
  }
  // условие Судьи 28.09: клетки П-07 ступени 3 (оси H3, H4, H5, H8, H13) показаны после вскрытия — поиск, не находка, не кандидаты
  const STAGE3 = "ступень 3, вскрыта (случай В): не кандидат";
  const isStage3 = k => isP07(k) && /^H(3|4|5|8|13) /.test((META[k] || {}).axis || "");
  // статус варианта — те же правила, что у прежней страницы (statusOf)
  function statusOf(k) {
    const m = META[k] || {};
    if (m.nocalc) return "нет расчёта";
    if (isStage3(k)) return STAGE3;
    if (m.status) return m.status;
    if (k === MAIN) return "база сравнения (В-121)";
    if (k === "btc4h_take" || k === "cand" || k === "nofilter") return "база сравнения";
    if (k === "g85" || k === "g85b") return "не проходит KPI (вердикт Судьи 28.09, случай В)";
    if (isP05(k)) { const g = kpi07For(k); return g ? (g.verdict === "не проходит" ? "не проходит" : "на проверке у Судьи") + " · KPI клетки: " + g.verdict : (P5.status || "на проверке у Судьи"); }
    if (isP02(k)) return "П-02: " + (p02Verdict(k) || "справочно");
    return "—";
  }
